sealed interface Expr permits Lit, Add {
    List<Expr> children();
}
record Lit(int value) implements Expr {
    public List<Expr> children() { return List.of(); }
}
record Add(Expr left, Expr right) implements Expr {
    public List<Expr> children() { return List.of(left, right); }
}

static int eval(Expr e) {
    return switch (e) {
        case Lit l -> l.value();
        case Add a -> eval(a.left()) + eval(a.right());
    };
}

abstract class Expr {
    abstract List<Expr> children();
    abstract <R> R accept(Visitor<R> v);
}
class Add extends Expr {
    final Expr left, right;
    Add(Expr l, Expr r) { left = l; right = r; }
    List<Expr> children() { return List.of(left, right); }
    <R> R accept(Visitor<R> v) { return v.visitAdd(this); }
}

